<?php
/**
 * Hard delete: legacy MRP test requisitions left in supplier_orders —
 * the PM00097 label rows generated by the dummy-FG test runs (55, 62, 75)
 * plus any orphaned PM00097 rows whose mrp_run_id points at a run that no
 * longer exists (79 — run 12 was deleted, leaving it soft-purged but still
 * counted by some queries).
 *
 * WHY hard delete instead of remove = 1: these are test records, not history.
 * A soft delete keeps them in table counts and in any query that forgets the
 * remove filter; the goal is that PENDING PO / RR for PM00097 reflects live
 * coverage only.
 *
 * Targets are evaluated live (not hard-coded IDs alone) so the migration
 * also catches PM00097 test/orphan rows added since the IDs were written:
 *   1. supplier_order_id IN (55, 62, 75) — explicit test records.
 *   2. item_id = PM00097 and mrp_run_id belongs to a dummy-FG test run
 *      (runs on FG001 / DFG 1: MRP1, MRP2, MRP3).
 *   3. item_id = PM00097 and mrp_run_id is orphaned (not in mrp_runs).
 * Legitimate PM00097 requisitions from real runs match none of these, so a
 * re-run after future real activity is still safe.
 *
 * Child rows are cleaned first: receiving_items.supplier_order_id (0 rows on
 * these targets; qc_inspections cascades via its ON DELETE CASCADE FK).
 * purchase_order_items has no po_ref column and no PM00097 rows — only
 * known dummy-coded lines are cleared defensively (0 rows in current data).
 *
 * NOT touched (out of scope): mrp_run_items snapshots (frozen history),
 * MRP runs 7/9/10 themselves, inventory_balances.qty_allocated committed by
 * those runs, and the qty_for_inspect QC-hold bucket (inventory, not a
 * supplier order).
 *
 * Idempotent: after the first pass no rows match, so re-running is a no-op.
 *
 * Usage:
 *   CLI:    php sql/pending/hard_delete_test_supplier_orders.php
 *   Runner: php sql/run_pending.php
 */
require_once __DIR__ . '/../../core/BaseModel.php';

$pdo = App\Core\BaseModel::getConnection();
$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

echo "=== Hard delete legacy test supplier orders ===\n";

// item_code is unique (migrate_item_code_unique) — resolves to one row.
$realId = (int) $pdo->query("SELECT item_id FROM items WHERE item_code = 'PM00097'")->fetchColumn();
if ($realId <= 0) {
    throw new RuntimeException("Real label item PM00097 not found in items — aborting.");
}

// Resolve the target set first so the run reports exactly what it removes.
$targetSql = "SELECT supplier_order_id FROM supplier_orders
              WHERE supplier_order_id IN (55, 62, 75)
              UNION
              SELECT supplier_order_id FROM supplier_orders
               WHERE item_id = {$realId}
                 AND (mrp_run_id IN (
                        SELECT run_id FROM mrp_runs
                         WHERE fg_item_id IN (SELECT item_id FROM items
                                               WHERE item_code IN ('FG001', 'DFG 1')))
                      OR (mrp_run_id IS NOT NULL
                          AND mrp_run_id NOT IN (SELECT run_id FROM mrp_runs)))";
$targets = array_map('intval', $pdo->query($targetSql)->fetchAll(PDO::FETCH_COLUMN));
echo '  Target rows: ' . count($targets)
    . ($targets ? ' (' . implode(', ', $targets) . ')' : '') . "\n";

$childDeleted = 0;
$deleted = 0;
if ($targets) {
    $inList = implode(',', $targets);

    // 1. Children first — receipts booked against these requisitions.
    $childDeleted = (int) $pdo->exec(
        "DELETE FROM receiving_items WHERE supplier_order_id IN ({$inList})"
    );

    // 2. The test requisitions themselves (hard delete).
    $deleted = (int) $pdo->exec(
        "DELETE FROM supplier_orders WHERE supplier_order_id IN ({$inList})"
    );
}

// 3. Defensive: dummy-coded customer-PO lines (purchase_order_items holds no
//    PM00097 rows; only the known dummy codes are removed).
$dummyCodes = "'item005', 'DIPM1', 'DIRM1', 'DIRM2', 'DIRM3', 'DIRM4'";
$poiDeleted = (int) $pdo->exec(
    "DELETE FROM purchase_order_items WHERE item_code IN ({$dummyCodes})"
);

// Verify: PENDING PO / RR for PM00097, same three sources as
// WarehouseModel::getPendingPoRrForItems() (which re-runs these queries
// live on every sheet render — no cached value to refresh).
$openPo = (float) $pdo->query(
    "SELECT COALESCE(SUM(GREATEST(quantity - COALESCE(received_qty, 0), 0)), 0)
       FROM supplier_orders
      WHERE `remove` = 0
        AND status IN ('pending', 'processed', 'partially_received', 'For Inspection')
        AND item_id = {$realId}"
)->fetchColumn();
$inspect = (float) $pdo->query(
    "SELECT COALESCE(SUM(GREATEST(qty_for_inspect, 0)), 0)
       FROM inventory_balances WHERE qty_for_inspect > 0 AND item_id = {$realId}"
)->fetchColumn();
$requested = (float) $pdo->query(
    "SELECT COALESCE(SUM(GREATEST(quantity - COALESCE(received_qty, 0), 0)), 0)
       FROM supplier_orders
      WHERE `remove` = 0 AND status = 'requested' AND item_id = {$realId}"
)->fetchColumn();

echo "  receiving_items children removed: {$childDeleted}\n";
echo "  supplier_orders hard deleted:     {$deleted}\n";
echo "  purchase_order_items removed:     {$poiDeleted}\n";
echo "  PENDING PO / RR for PM00097 now:\n";
echo "    open PO remainders:  {$openPo}\n";
echo "    QC-hold (inspect):   {$inspect}\n";
echo "    open requested:      {$requested}\n";
echo "    total:               " . ($openPo + $inspect + $requested) . "\n";
echo "=== Done ===\n";
